/**
 * Regenerates src/game/data/countries.generated.ts from the authoritative world
 * output (world metadata, province ownership/details, and the surface field).
 *
 * The generated file is lobby-time country data so the campaign country picker
 * needs no world fetch. It is a CACHE of the world output, never a second
 * source of truth: tests/game/country-catalog.test.ts re-derives the same data
 * and fails if the committed file drifts (guardrail 1). Run this after any
 * change to the world seed / political data:
 *
 *   node scripts/generate-country-catalog.mjs
 */

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const WORLD_JSON = path.join(ROOT, 'public/world/world.json');
const OWNERS = path.join(ROOT, 'public/world/province-owners.u32');
const PROVINCE_DETAILS = path.join(ROOT, 'public/world/province-details.json');
const SURFACE = path.join(ROOT, 'public/world/surface.rgba8');
const OUT = path.join(ROOT, 'src/game/data/countries.generated.ts');

/** 2-letter flag codes for countries that have art in src/ui/assets/flags/. */
export const FLAG_CODES = {
  Germany: 'de', Spain: 'es', France: 'fr', Turkey: 'tr', Italy: 'it', Poland: 'pl',
  Egypt: 'eg', 'South Africa': 'za', 'Saudi Arabia': 'sa', Persia: 'ir', Ireland: 'ie',
  Greece: 'gr', Bulgaria: 'bg', Romania: 'ro', Netherlands: 'nl', Belgium: 'be',
  Denmark: 'dk', Norway: 'no', Sweden: 'se', Finland: 'fi', Iceland: 'is', Austria: 'at',
  Switzerland: 'ch', Portugal: 'pt', Japan: 'jp', Luxembourg: 'lu', Czechia: 'cz',
  Ethiopia: 'et', 'New Zealand': 'nz',
};

/** Derive the catalogue rows from already-parsed world data. Shared with the test. */
export function deriveCatalogCountries(worldJson, ownersU32, provinceDetailsJson, surfaceRgba8) {
  const provinceCount = new Map();
  for (const owner of ownersU32) {
    if (owner === 0) continue;
    provinceCount.set(owner, (provinceCount.get(owner) ?? 0) + 1);
  }

  // Match buildWorldData's game-start city rule exactly: a province is urban
  // when the surface field at its authored centre has terrain class 4.
  const cityCount = new Map();
  const worldWidth = worldJson.world.width;
  const worldHeight = worldJson.world.height;
  const surfaceWidth = worldJson.fields.surface.width;
  const surfaceHeight = worldJson.fields.surface.height;
  for (const province of provinceDetailsJson.provinces) {
    const px = Math.min(surfaceWidth - 1,
      Math.floor((((province.center[0] % worldWidth) + worldWidth) % worldWidth) / worldWidth * surfaceWidth));
    const pz = Math.min(surfaceHeight - 1,
      Math.max(0, Math.floor(province.center[1] / worldHeight * surfaceHeight)));
    const base = (pz * surfaceWidth + px) * 4;
    if (surfaceRgba8[base + 3] === 0 || surfaceRgba8[base] !== 4) continue;
    const owner = ownersU32[province.id + 1] ?? 0;
    if (owner === 0) continue;
    cityCount.set(owner, (cityCount.get(owner) ?? 0) + 1);
  }
  return worldJson.politics.countries
    .map((country) => ({
      id: country.id,
      name: country.name,
      color: country.color,
      colorFamily: country.colorFamily,
      capitalProvinceId: country.capitalProvinceId,
      provinceCount: provinceCount.get(country.id) ?? 0,
      cityCount: cityCount.get(country.id) ?? 0,
      flag: FLAG_CODES[country.name] ?? null,
    }))
    .filter((country) => country.provinceCount > 0)
    .sort((a, b) => a.id - b.id);
}

export function renderCatalogModule(rows) {
  const body = rows
    .map((row) => `  ${JSON.stringify(row)},`)
    .join('\n');
  return `// GENERATED by scripts/generate-country-catalog.mjs from public/world/world.json
// authoritative world package. Lobby-time country data so the
// campaign country picker needs no world fetch. This is a CACHE of the world
// output; tests/game/country-catalog.test.ts fails if it drifts. Do not hand-edit.

export interface CatalogCountry {
  readonly id: number;
  readonly name: string;
  readonly color: string;
  readonly colorFamily: number;
  readonly capitalProvinceId: number;
  readonly provinceCount: number;
  /** Urban provinces owned at game start. */
  readonly cityCount: number;
  /** 2-letter code for src/ui/assets/flags/<code>.svg, or null when no flag art exists. */
  readonly flag: string | null;
}

export const CATALOG_COUNTRIES: readonly CatalogCountry[] = [
${body}
];

export const CATALOG_COUNTRY_BY_ID: ReadonlyMap<number, CatalogCountry> =
  new Map(CATALOG_COUNTRIES.map((country) => [country.id, country]));

export const CATALOG_COUNTRY_BY_NAME: ReadonlyMap<string, CatalogCountry> =
  new Map(CATALOG_COUNTRIES.map((country) => [country.name.toLowerCase(), country]));
`;
}

export async function generate() {
  const [worldText, ownersBuffer, provinceDetailsText, surfaceBuffer] = await Promise.all([
    readFile(WORLD_JSON, 'utf8'),
    readFile(OWNERS),
    readFile(PROVINCE_DETAILS, 'utf8'),
    readFile(SURFACE),
  ]);
  const worldJson = JSON.parse(worldText);
  const ownersU32 = new Uint32Array(
    ownersBuffer.buffer, ownersBuffer.byteOffset, ownersBuffer.byteLength / Uint32Array.BYTES_PER_ELEMENT,
  );
  const rows = deriveCatalogCountries(
    worldJson, ownersU32, JSON.parse(provinceDetailsText), surfaceBuffer,
  );
  const module = renderCatalogModule(rows);
  await mkdir(path.dirname(OUT), { recursive: true });
  await writeFile(OUT, module);
  console.log(`Wrote ${path.relative(ROOT, OUT)} — ${rows.length} countries.`);
  return module;
}

// Run only when invoked directly (not when imported by the drift test).
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await generate();
}
